from __future__ import annotations

def build_content_preview(facts:dict)->dict:
    model=facts['model_name']; sizes=f"{facts['eu_sizes'][0]}–{facts['eu_sizes'][-1]}"; tech=', '.join(facts.get('technology',[]))
    bg=f"""<h2>Работни обувки Diadora {model}</h2><p><strong>Diadora {model}</strong> са ниски защитни обувки клас <strong>S3S</strong> за професионална употреба.</p><h2>Защита и конструкция</h2><ul><li><strong>Защитен клас:</strong> S3S</li><li><strong>Бомбе:</strong> алуминиево, 200 J</li><li><strong>Защита от пробиване:</strong> {facts['anti_puncture']}</li><li><strong>ESD:</strong> да</li><li><strong>Междинна подметка:</strong> {facts['midsole']}</li><li><strong>Външна подметка:</strong> {facts['outsole']}</li><li><strong>Ширина:</strong> {facts['width']}</li><li><strong>Размери:</strong> EU {sizes}</li></ul><h2>Технологии</h2><p>{tech}. Технологиите са част от конструкцията, посочена от производителя.</p><h2>Приложение</h2><p>Подходящи за индустрия, логистика, складова дейност, сервизни и технически дейности, монтаж и производство, когато се изисква клас S3S.</p><h2>Размери и избор</h2><p>Официалният диапазон е EU {sizes}. При избор се съобразяват дължина и ширина на ходилото, работни чорапи и продължителност на носене.</p><h2>Често задавани въпроси</h2><h3>Какъв е класът?</h3><p>S3S.</p><h3>Какво е бомбето?</h3><p>Алуминиево защитно бомбе 200 J.</p><h3>Има ли защита от пробиване?</h3><p>Да – {facts['anti_puncture']}.</p><h3>Подходящи ли са за ESD?</h3><p>Да.</p><h3>Какви размери има?</h3><p>EU {sizes}.</p>"""
    en=f"""<h2>Diadora {model} safety shoes</h2><p><strong>Diadora {model}</strong> are low-top <strong>S3S</strong> safety shoes for professional use.</p><h2>Protection and construction</h2><ul><li><strong>Safety class:</strong> S3S</li><li><strong>Toe cap:</strong> aluminium, 200 J</li><li><strong>Anti-puncture:</strong> {facts['anti_puncture']}</li><li><strong>ESD:</strong> yes</li><li><strong>Midsole:</strong> {facts['midsole']}</li><li><strong>Outsole:</strong> {facts['outsole']}</li><li><strong>Width:</strong> {facts['width']}</li><li><strong>Sizes:</strong> EU {sizes}</li></ul><h2>Technologies</h2><p>{tech}. These technologies form part of the manufacturer-specified construction.</p><h2>Professional use</h2><p>Suitable for industry, logistics, warehouses, technical service, installation and manufacturing where S3S footwear is required.</p><h2>Sizes and selection</h2><p>The official range is EU {sizes}. Consider foot length and width, work socks and expected wearing time.</p><h2>Frequently asked questions</h2><h3>What is the safety class?</h3><p>S3S.</p><h3>What toe cap is used?</h3><p>A 200 J aluminium safety toe cap.</p><h3>Is anti-puncture protection included?</h3><p>Yes – {facts['anti_puncture']}.</p><h3>Is it suitable for ESD environments?</h3><p>Yes.</p><h3>What sizes are available?</h3><p>EU {sizes}.</p>"""
    return {'bg':{'title':f'Работни обувки Diadora {model}','h1':f'Работни обувки Diadora {model}','meta_title':f'Работни обувки Diadora {model} | S3S','meta_description':f'Diadora {model}: S3S, алуминиево бомбе 200 J, {facts["anti_puncture"]}, ESD, FO HRO SR, размери EU {sizes}.','short_description':f'Ниски защитни обувки Diadora {model}, S3S, алуминиево бомбе 200 J, {facts["anti_puncture"]}, ESD и FO HRO SR.','long_description_html':bg},'en':{'title':f'Diadora {model} safety shoes','h1':f'Diadora {model} safety shoes','meta_title':f'Diadora {model} Safety Shoes | S3S','meta_description':f'Diadora {model}: S3S, 200 J aluminium toe cap, {facts["anti_puncture"]}, ESD, FO HRO SR, EU {sizes}.','short_description':f'Low-top Diadora {model} S3S safety shoes with 200 J aluminium toe cap, {facts["anti_puncture"]}, ESD and FO HRO SR.','long_description_html':en},'evidence_trace':{k:facts.get(k) for k in ['manufacturer_item','protection_class','colour','toe_cap','anti_puncture','width','technology','esd','midsole','outsole','eu_sizes']}}
